  "recovered_c": "uint64_t fn_12(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n    if (len < 0x18 || out_cap < 8) {\n        return VERA_ERR;\n    }\n\n    uint64_t hash = (uint64_t)arg;\n    uint64_t polynomial = 0x1f9;\n    uint64_t constant = 0x2d6b;\n\n    for (size_t i = 0; i < len; i++) {\n        hash += ((uint64_t)in[i] * polynomial) ^ (hash >> 5);\n        hash = (hash * constant) ^ (hash >> 11);\n    }\n\n    *out = (uint8_t)(hash & 0xFF);\n    *out++ = (uint8_t)((hash >> 8) & 0xFF);\n    *out++ = (uint8_t)((hash >> 16) & 0xFF);\n    *out++ = (uint8_t)((hash >> 24) & 0xFF);\n    *out++ = (uint8_t)((hash >> 32) & 0xFF);\n    *out++ = (uint8_t)((hash >> 40) & 0xFF);\n    *out++ = (uint8_t)((hash >> 48) & 0xFF);\n    *out++ = (uint8_t)((hash >> 56) & 0xFF);\n\n    return 8;\n}"
